package com.corecs.solid.rules;import com.corecs.solid.model.*;import java.util.*;public class DipRule implements SolidRule{public List<Issue> analyze(List<ClassInfo> cs){Set<String> interfaces=cs.stream().filter(ClassInfo::interfaceType).map(ClassInfo::name).collect(java.util.stream.Collectors.toSet());List<Issue> o=new ArrayList<>();for(var c:cs)if(!c.interfaceType()){for(var d:c.dependencies())if(!interfaces.contains(d)&&cs.stream().anyMatch(x->x.name().equals(d)))o.add(new Issue("DIP","Potential",c.name(),"Direct dependency on concrete type: "+d,"The class appears to depend directly on another concrete class in its own analyzed source.","Depend on a stable abstraction when the dependency is volatile or needs substitution."));}return o;}}
